/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_people_after_insert` AFTER INSERT ON `tb_people` FOR EACH ROW BEGIN
    INSERT INTO tb_logs (
        table_name,
        table_operation,
        db_user,
        operation_date,
        operation_description,
        operation_status
    )
    VALUES (
        'tb_people',
        'Create',
        USER(),
        CURRENT_TIMESTAMP,
        CONCAT_WS(' | ',
            CONCAT('Person ID: ', NEW.person_ID),
            CONCAT('User ID: ', IFNULL(NEW.user_ID, 'N/A')),
            CONCAT('Título: ', IFNULL(NEW.courtesy_title, 'N/A')),
            CONCAT('Nombres: ', IFNULL(NEW.given_names, 'N/A')),
            CONCAT('Apellidos: ', IFNULL(NEW.family_names, 'N/A')),
            CONCAT('Fecha Nacimiento: ', IFNULL(NEW.birth_date, 'N/A')),
            CONCAT('Género: ', IFNULL(NEW.gender, 'N/A')),
            CONCAT('Código País: ', IFNULL(NEW.country_code, 'N/A')),
            CONCAT('Teléfono: ', IFNULL(NEW.phone, 'N/A')),
            CONCAT('Estado: ', IFNULL(NEW.status, 'N/A')),
            CONCAT('Fecha creación: ', IFNULL(NEW.creation_date, 'N/A'))
        ),
        b'1'
    );
END */;;
