/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_people_after_update` AFTER UPDATE ON `tb_people` FOR EACH ROW BEGIN
    INSERT INTO tb_logs (
        table_name,
        table_operation,
        db_user,
        operation_date,
        operation_description,
        operation_status
    )
    VALUES (
        'tb_people',
        'Update',
        USER(),
        CURRENT_TIMESTAMP,
        CONCAT_WS(' | ',
            CONCAT('Person ID: ', NEW.person_ID),
            CONCAT('User ID: ', IFNULL(OLD.user_ID, 'N/A'), ' -> ', IFNULL(NEW.user_ID, 'N/A')),
            CONCAT('Título: ', IFNULL(OLD.courtesy_title, 'N/A'), ' -> ', IFNULL(NEW.courtesy_title, 'N/A')),
            CONCAT('Nombres: ', IFNULL(OLD.given_names, 'N/A'), ' -> ', IFNULL(NEW.given_names, 'N/A')),
            CONCAT('Apellidos: ', IFNULL(OLD.family_names, 'N/A'), ' -> ', IFNULL(NEW.family_names, 'N/A')),
            CONCAT('Fecha Nacimiento: ', IFNULL(OLD.birth_date, 'N/A'), ' -> ', IFNULL(NEW.birth_date, 'N/A')),
            CONCAT('Género: ', IFNULL(OLD.gender, 'N/A'), ' -> ', IFNULL(NEW.gender, 'N/A')),
            CONCAT('Código País: ', IFNULL(OLD.country_code, 'N/A'), ' -> ', IFNULL(NEW.country_code, 'N/A')),
            CONCAT('Teléfono: ', IFNULL(OLD.phone, 'N/A'), ' -> ', IFNULL(NEW.phone, 'N/A')),
            CONCAT('Estado: ', IFNULL(OLD.status, 'N/A'), ' -> ', IFNULL(NEW.status, 'N/A')),
            CONCAT('Última actualización: ', IFNULL(NEW.last_update, CURRENT_TIMESTAMP))
        ),
        b'1'
    );
END */;;
DELIMITER ;
