/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_people_after_delete` AFTER DELETE ON `tb_people` FOR EACH ROW BEGIN
    INSERT INTO tb_logs (
        table_name,
        table_operation,
        db_user,
        operation_date,
        operation_description,
        operation_status
    )
    VALUES (
        'tb_people',
        'Delete',
        USER(),
        CURRENT_TIMESTAMP,
        CONCAT_WS(' | ',
            CONCAT('Person ID eliminado: ', OLD.person_ID),
            CONCAT('User ID: ', IFNULL(OLD.user_ID, 'N/A')),
            CONCAT('Nombres: ', IFNULL(OLD.given_names, 'N/A')),
            CONCAT('Apellidos: ', IFNULL(OLD.family_names, 'N/A')),
            CONCAT('Teléfono: ', IFNULL(OLD.phone, 'N/A'))
        ),
        b'1'
    );
END */;;
