            CONCAT('Por Defecto: ', IFNULL(OLD.is_default, 0), ' -> ', IFNULL(NEW.is_default, 0)),
            CONCAT('Estado: ', IFNULL(OLD.status, 'N/A'), ' -> ', IFNULL(NEW.status, 'N/A')),
            CONCAT('Última actualización: ', IFNULL(NEW.last_update, CURRENT_TIMESTAMP))
        ),
        b'1'
    );
END */;;
