/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_users_after_insert` AFTER INSERT ON `tb_users` FOR EACH ROW BEGIN
    INSERT INTO `tb_logs` (
        `table_name`,
        `table_operation`,
        `db_user`,
        `operation_date`,
        `operation_description`,
        `operation_status`
    )
    VALUES (
        'tb_users',
        'Create',
        USER(),
        CURRENT_TIMESTAMP,
        CONCAT(
            'Usuario creado ID: ', NEW.ID,
            ', email: ', NEW.email,
            ', nick: ', NEW.nick,
            ', creation_date: ', NEW.creation_date,
            ', status: ', NEW.status
        ),
        b'1'
    );
END */;;
