CREATE DEFINER=`jessica.cruz`@`%` FUNCTION `fn_get_random_birthdate`(min_age INT, max_age INT) RETURNS date
    DETERMINISTIC
BEGIN
    DECLARE min_date DATE;
    DECLARE max_date DATE;
    
    SET max_date = DATE_SUB(CURDATE(), INTERVAL min_age YEAR);
    SET min_date = DATE_SUB(CURDATE(), INTERVAL max_age YEAR);
    
    RETURN DATE_ADD(min_date, INTERVAL FLOOR(RAND() * DATEDIFF(max_date, min_date)) DAY);
END ;;
DELIMITER ;
