CREATE DEFINER=`jessica.cruz`@`%` FUNCTION `fn_get_random_phone`() RETURNS varchar(30) CHARSET utf8mb4
    DETERMINISTIC
BEGIN
    RETURN CONCAT('+1 ', FLOOR(200 + (RAND() * 800)), ' ', FLOOR(100 + (RAND() * 900)), ' ', FLOOR(1000 + (RAND() * 9000)));
END ;;
