CREATE DEFINER=`jessica.cruz`@`%` FUNCTION `fn_get_random_status`(active_percentage DECIMAL(3,2)) RETURNS tinyint
    DETERMINISTIC
BEGIN
    -- Si RAND() genera <= 0.80 retorna 1 (Activo), de lo contrario 0 (Inactivo)
    IF RAND() <= active_percentage THEN
        RETURN 1;
    ELSE
        RETURN 0;
    END IF;
END ;;
DELIMITER ;
